#!/usr/bin/env python3
"""Patches the Android project generated by `flutter create` so that the app
works with: local notifications, biometric lock, internet (AI assistant), Arabic label, desugaring.
Run from the project root AFTER `flutter create`. Safe to run more than once."""
import glob
import os
import re
import sys

ROOT = os.getcwd()
MANIFEST = os.path.join(ROOT, "android/app/src/main/AndroidManifest.xml")

PERMS = [
    "android.permission.INTERNET",  # المساعد الذكي (Gemini) فقط
    "android.permission.POST_NOTIFICATIONS",
    "android.permission.RECEIVE_BOOT_COMPLETED",
    "android.permission.VIBRATE",
    "android.permission.USE_BIOMETRIC",
]

RECEIVERS = """
        <receiver android:exported="false" android:name="com.dexterous.flutterlocalnotifications.ScheduledNotificationReceiver" />
        <receiver android:exported="false" android:name="com.dexterous.flutterlocalnotifications.ScheduledNotificationBootReceiver">
            <intent-filter>
                <action android:name="android.intent.action.BOOT_COMPLETED"/>
                <action android:name="android.intent.action.MY_PACKAGE_REPLACED"/>
                <action android:name="android.intent.action.QUICKBOOT_POWERON" />
                <action android:name="com.htc.intent.action.QUICKBOOT_POWERON"/>
            </intent-filter>
        </receiver>
"""


QUERIES = """
    <queries>
        <intent><action android:name="android.intent.action.VIEW"/><data android:scheme="tel"/></intent>
        <intent><action android:name="android.intent.action.VIEW"/><data android:scheme="https"/></intent>
        <intent><action android:name="android.intent.action.VIEW"/><data android:scheme="mailto"/></intent>
    </queries>
"""


def read(p):
    with open(p, encoding="utf-8") as f:
        return f.read()


def write(p, s):
    with open(p, "w", encoding="utf-8") as f:
        f.write(s)


def patch_manifest():
    s = read(MANIFEST)
    # permissions
    add = ""
    for p in PERMS:
        if p not in s:
            add += f'    <uses-permission android:name="{p}"/>\n'
    if add:
        s = re.sub(r"(<manifest[^>]*>\n?)", lambda m: m.group(1) + add, s, count=1)
    # label + disable cloud auto-backup (privacy)
    s = re.sub(r'android:label="[^"]*"', 'android:label="أجندة المحامي"', s, count=1)
    if "android:allowBackup" not in s:
        s = s.replace("<application", '<application\n        android:allowBackup="false"', 1)
    # queries (url_launcher: اتصال / واتساب / بريد على أندرويد 11+)
    if "<queries>" not in s:
        s = s.replace("<application", QUERIES + "    <application", 1)
    # receivers
    if "ScheduledNotificationReceiver" not in s:
        s = s.replace("</application>", RECEIVERS + "    </application>", 1)
    write(MANIFEST, s)
    print("patched AndroidManifest.xml")


def patch_main_activity():
    files = glob.glob(os.path.join(ROOT, "android/app/src/main/**/MainActivity.*"), recursive=True)
    for f in files:
        s = read(f)
        if "FlutterFragmentActivity" in s:
            continue
        write(f, s.replace("FlutterActivity", "FlutterFragmentActivity"))
        print("patched", os.path.relpath(f, ROOT))


def patch_gradle():
    kts = os.path.join(ROOT, "android/app/build.gradle.kts")
    groovy = os.path.join(ROOT, "android/app/build.gradle")
    if os.path.exists(kts):
        path, is_kts = kts, True
    elif os.path.exists(groovy):
        path, is_kts = groovy, False
    else:
        sys.exit("android/app/build.gradle(.kts) not found")
    s = read(path)

    # minSdk 23 (required by local_auth / notifications)
    s = re.sub(r"minSdk\s*=\s*flutter\.minSdkVersion", "minSdk = 23", s)
    s = re.sub(r"minSdkVersion\s+flutter\.minSdkVersion", "minSdkVersion 23", s)

    if "oreLibraryDesugaring" not in s:
        flag = "isCoreLibraryDesugaringEnabled = true" if is_kts else "coreLibraryDesugaringEnabled true"
        s = re.sub(r"(compileOptions\s*\{)", lambda m: m.group(1) + "\n        " + flag, s, count=1)
        dep = (
            'coreLibraryDesugaring("com.android.tools:desugar_jdk_libs:2.1.4")'
            if is_kts
            else "coreLibraryDesugaring 'com.android.tools:desugar_jdk_libs:2.1.4'"
        )
        if re.search(r"^dependencies\s*\{", s, flags=re.M):
            s = re.sub(r"^(dependencies\s*\{)", lambda m: m.group(1) + "\n    " + dep, s, count=1, flags=re.M)
        else:
            s += "\ndependencies {\n    " + dep + "\n}\n"
    write(path, s)
    print("patched", os.path.relpath(path, ROOT))


def cleanup():
    t = os.path.join(ROOT, "test/widget_test.dart")
    if os.path.exists(t):
        os.remove(t)


if __name__ == "__main__":
    if not os.path.exists(MANIFEST):
        sys.exit("Run `flutter create` first (android/ folder not found).")
    patch_manifest()
    patch_main_activity()
    patch_gradle()
    cleanup()
    print("done")
